namespace Fanex.Age.UI.TotalBets
{

    public partial class NumberGame_Page : TotalBets_Page
    {

        #region Override

        public override void RenderContent(HtmlTextWriter writer)
        {
            DataTable NumberGameList = View as DataTable;

            NumberGame_Template tpl = new NumberGame_Template();
            tpl.Contents.LeagueContents.Clear();

            if (NumberGameList.Rows.Count > 0)
            {
                tpl.Contents.NotFound.Hide();

                // Render league content
                int currentLeagueId = 0;
                int matchIndex = 0;
                NumberGame_Contents_LeagueContents_Block leagueBlock = new NumberGame_Contents_LeagueContents_Block();
                NumberGame_Contents_LeagueContents_MatchContents_Block matchBlock = new NumberGame_Contents_LeagueContents_MatchContents_Block();

                for (int i = 0; i < NumberGameList.Rows.Count; i++)
                {
                    DataRow dr = NumberGameList.Rows[i];

                    int leagueId = Convert.ToInt32(dr["leagueid"]);

                    if (i == 0 || currentLeagueId != leagueId)
                    {
                        // New league, ignore first row
                        if (i != 0) tpl.Contents.LeagueContents.Append(leagueBlock);

                        matchIndex = 1;
                        currentLeagueId = leagueId;

                        leagueBlock.MatchContents.Clear();
                        leagueBlock.LeagueName = Sunplus.Agent.Model.BL.Cache.CacheRef.GetLeagueName(leagueId);
                    }
                    else
                    {
                        matchIndex++;
                    }

                    RenderMatchRow(matchBlock, dr, matchIndex, i + 1);

                    leagueBlock.MatchContents.Append(matchBlock);
                }

                if (leagueBlock != null) tpl.Contents.LeagueContents.Append(leagueBlock);
            }


            if (_fullMode)
            {
                writer.Write(tpl);
            }
            else
            {
                writer.Write(tpl.Contents);
            }
        }

        public override object ValidateRequest(System.Collections.Hashtable p)
        {
            return null;
        }

        public override object InvokeData(System.Collections.Hashtable p)
        {
            return _TotalBetsBO.GetNumberGame();
        }
        #endregion

        #region Utility
        /// <summary>
        /// Render match row
        /// Only show link to bet list if odd and even is not null
        /// </summary>
        /// <param name="matchBlock"></param>
        /// <param name="dr"></param>
        /// <param name="matchIndex"></param>
        /// <param name="rowIndex"></param>
        private void RenderMatchRow(NumberGame_Contents_LeagueContents_MatchContents_Block matchBlock, DataRow dr, int matchIndex, int rowIndex)
        {
            // Render match content
            matchBlock.ColorOver = Fanex.Age.UI.Common.RowBgOver;
            matchBlock.ColorClass = (matchIndex % 2) == 0 ? Fanex.Age.UI.Common.RowBgEven : Fanex.Age.UI.Common.RowBgOdd;
            
            matchBlock.NoValue = rowIndex.ToString();
            matchBlock.GameNo = dr["matchcode"].ToString();
            matchBlock.MatchId = dr["matchid"].ToString();


            #region get value infomation
            decimal Warrior_2ndBall = (decimal)dr["Warrior_2ndBall"];
            decimal Warrior_3rdBall = (decimal)dr["Warrior_3rdBall"];

            decimal overUnderFirstBall = ((decimal)dr["over_1stBall"]) - ((decimal)dr["under_1stBall"]);
            decimal oddEvenFirstBall = ((decimal)dr["odd_1stBall"]) - ((decimal)dr["even_1stBall"]);

            decimal overUnderLastBall = ((decimal)dr["over_lastBall"]) - ((decimal)dr["under_lastBall"]);
            decimal oddEvenLastBall = ((decimal)dr["odd_lastBall"]) - ((decimal)dr["even_lastBall"]);

            decimal overUnderNext = ((decimal)dr["over_next"]) - ((decimal)dr["under_next"]);
            decimal oddEvenNext = ((decimal)dr["odd_next"]) - ((decimal)dr["even_next"]);
            decimal highLow = ((decimal)dr["high"]) - ((decimal)dr["low"]);

            decimal NextCombo_OverOdd = (decimal)dr["NextCombo_OverOdd"];
            decimal NextCombo_OverEven = (decimal)dr["NextCombo_OverEven"];
            decimal NextCombo_UnderOdd = (decimal)dr["NextCombo_UnderOdd"];
            decimal NextCombo_UnderEven = (decimal)dr["NextCombo_UnderEven"];

            decimal oddEvenFullTime = ((decimal)dr["odd_fullTime"]) - ((decimal)dr["even_fullTime"]);
            decimal NumberGroupLive = (decimal)dr["NumberGroupLive"];
            decimal NumberGroupPre = (decimal)dr["NumberGroupPre"];
            #endregion

            #region get betcount infomation
            int betcountWarrior2ndBall = (int)dr["betcount_Warrior_2ndBall"];
            int betcountWarrior3rdBall = (int)dr["betcount_Warrior_3rdBall"];

            int betCountOU1st = (int)dr["betcount_OU1stBall"];
            int betCountOULast = (int)dr["betcount_OULastBall"];

            int betCountOE1st = (int)dr["betcount_OE1stBall"];
            int betCountOELast = (int)dr["betcount_OElastBall"];            

            int betCountOUNext = (int)dr["betcount_OUNext"];
            int betCountOENext = (int)dr["betcount_OENext"];
            int betCountHighLow = (int)dr["betcount_highlow"];

            int betCountNextComboOverOdd = (int)dr["betcount_nextcombo_OverOdd"];
            int betCountNextComboOverEven = (int)dr["betcount_nextcombo_OverEven"];
            int betCountNextComboUnderOdd = (int)dr["betcount_nextcombo_UnderOdd"];
            int betCountNextComboUnderEven = (int)dr["betcount_nextcombo_UnderEven"];

            int betCountOEFT = (int)dr["betcount_OEfullTime"];
            int betcountNumberGroupLive = (int)dr["betcount_NumberGroupLive"];
            int betcountNumberGroupPre = (int)dr["betcount_NumberGroupPre"];
            #endregion

            #region Render template
            matchBlock.Warrior_2ndBall = betcountWarrior2ndBall != 0 ? NegativeNumberRoundColor(Warrior_2ndBall) : "";
            matchBlock.Warrior_3rdBall = betcountWarrior3rdBall != 0 ? NegativeNumberRoundColor(Warrior_3rdBall) : "";

            matchBlock.OverUnderFirstBall = betCountOU1st != 0 ? NegativeNumberRoundColor(overUnderFirstBall) : "";
            matchBlock.OverUnderLastBall = betCountOULast != 0 ? NegativeNumberRoundColor(overUnderLastBall) : "";     
       
            matchBlock.OddEvenFirstBall = betCountOE1st != 0 ? NegativeNumberRoundColor(oddEvenFirstBall) : "";
            matchBlock.OddEvenLastBall = betCountOELast != 0 ? NegativeNumberRoundColor(oddEvenLastBall) : "";            

            matchBlock.OverUnderNext = betCountOUNext != 0 ? NegativeNumberRoundColor(overUnderNext) : "";
            matchBlock.OddEvenNext = betCountOENext != 0 ? NegativeNumberRoundColor(oddEvenNext) : "";

            matchBlock.HighLow = betCountHighLow != 0 ? NegativeNumberRoundColor(highLow) : "";

            matchBlock.NextCombo_OverOdd = betCountNextComboOverOdd != 0 ? NegativeNumberRoundColor(NextCombo_OverOdd) : "";
            matchBlock.NextCombo_OverEven = betCountNextComboOverEven != 0 ? NegativeNumberRoundColor(NextCombo_OverEven) : "";
            matchBlock.NextCombo_UnderOdd = betCountNextComboUnderOdd != 0 ? NegativeNumberRoundColor(NextCombo_UnderOdd) : "";
            matchBlock.NextCombo_UnderEven = betCountNextComboUnderEven != 0 ? NegativeNumberRoundColor(NextCombo_UnderEven) : "";

            matchBlock.OddEvenFullTime = betCountOEFT != 0 ? NegativeNumberRoundColor(oddEvenFullTime) : "";
            matchBlock.NumberGroupLive = betcountNumberGroupLive != 0 ? NegativeNumberRoundColor(NumberGroupLive) : "";
            matchBlock.NumberGroupPre = betcountNumberGroupPre != 0 ? NegativeNumberRoundColor(NumberGroupPre) : "";
            #endregion
        }

        /// <summary>
        /// Round color for negative number
        /// </summary>
        /// <param name="number"></param>
        /// <returns></returns>
        private static string NegativeNumberRoundColor(object number)
        {
            decimal num = Convert.ToDecimal(number);

            return (num < 0) ? "<font color='#eb6003'>" + Formater.DecFormat(num, 0) + "</font>" : Formater.DecFormat(num, 0);
        }

        #endregion
    }

}
